class Solution {
    public boolean hasAlternatingBits(int n) {
        int mask = n ^ (n >> 1);
        return (mask & (mask + 1)) == 0;
    }
}

class Solution {
    public boolean hasAlternatingBits(int n) {
        while (n > 1) {
            int pair = n & 3;
            if (pair == 0 || pair == 3) {
                return false;
            }
            n >>= 1;
        }
        return true;
    }
}

class Solution {
    public boolean hasAlternatingBits(int n) {
        int pattern = 1;
        while (pattern < n) {
            if (pattern > (Integer.MAX_VALUE >> 1)) {
                return false;
            }
            int nextBit = (pattern & 1) == 0 ? 1 : 0;
            pattern = (pattern << 1) | nextBit;
        }
        return pattern == n;
    }
}

class Solution {
    public boolean hasAlternatingBits(int n) {
        String bits = Integer.toBinaryString(n);
        for (int i = 1; i < bits.length(); i++) {
            if (bits.charAt(i) == bits.charAt(i - 1)) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean hasAlternatingBits(int n) {
        if (n < 2) {
            return true;
        }
        int low = n & 1;
        int next = (n >> 1) & 1;
        if (low == next) {
            return false;
        }
        return hasAlternatingBits(n >> 1);
    }
}
